using GrapSolution.Application;
using GrapSolution.Domain;
using GrapSolution.Infrastructure;
using Microsoft.EntityFrameworkCore;
namespace GrapSolution.Api;
public static partial class Endpoints
{
    private static void MapAdmin(RouteGroupBuilder auth)
    {
        var admin = auth.MapGroup("/admin");
        admin.MapGet("/dashboard", (HttpContext ctx, GrapDbContext db, int? days) =>
        {
            var a = ctx.Actor(); a.Require(Roles.Staff); var now = DateTime.UtcNow; var localDate = TimeZoneInfo.ConvertTimeFromUtc(now, TimeZoneInfo.FindSystemTimeZoneById("Asia/Ho_Chi_Minh")).Date; var today = localDate.AddHours(-7);
            var rides = db.Set<Ride>().Where(r => r.ZoneId == a.ZoneId).ToList(); var recent = rides.Where(r => r.CreatedAt >= today).ToList(); var yesterday = rides.Where(r => r.CreatedAt >= today.AddDays(-1) && r.CreatedAt < today).ToList(); var drivers = db.Set<Driver>().Where(d => d.ZoneId == a.ZoneId).ToList();
            var chart = Enumerable.Range(0, Math.Clamp(days ?? 7, 1, 30)).Select(i => { var date = today.AddDays(i - Math.Clamp(days ?? 7, 1, 30) + 1); var daily = rides.Where(r => r.CreatedAt >= date && r.CreatedAt < date.AddDays(1)).ToList(); return new { date = date.AddHours(7).ToString("yyyy-MM-dd"), rides = daily.Count, grossFare = daily.Where(r => r.Status == "COMPLETED").Sum(r => r.Fare.GrossFare), platformFees = daily.Where(r => r.Status == "COMPLETED").Sum(r => r.Fare.PlatformCommission) }; });
            var healthy = drivers.Count(d => d.Online && d.HeartbeatAt > now.AddSeconds(-30) && d.LocationAt > now.AddSeconds(-30));
            return new { today = new { rides = recent.Count, grossFare = recent.Where(r => r.Status == "COMPLETED").Sum(r => r.Fare.GrossFare), completed = recent.Count(r => r.Status == "COMPLETED"), canceled = recent.Count(r => r.Status == "CANCELED"), successRate = recent.Count == 0 ? 0 : decimal.Round(recent.Count(r => r.Status == "COMPLETED") * 100m / recent.Count, 1), onlineDrivers = healthy }, yesterday = new { rides = yesterday.Count, grossFare = yesterday.Where(r => r.Status == "COMPLETED").Sum(r => r.Fare.GrossFare) }, activeRides = rides.Count(r => RideStates.IsActive(r.Status)), pendingDrivers = drivers.Count(d => d.ReviewStatus == "PENDING_REVIEW"), openTickets = db.Set<SupportTicket>().Count(t => t.ZoneId == a.ZoneId && t.Status != "RESOLVED" && t.Status != "CLOSED"), paymentIssues = db.Set<Payment>().Count(p => p.Status == "PENDING" && db.Set<Ride>().Any(r => r.Id == p.RideId && r.ZoneId == a.ZoneId)), chart, services = rides.GroupBy(r => r.ServiceTypeCode).Select(g => new { code = g.Key, count = g.Count() }), serverTime = now, developmentData = appEnvironment(ctx) };
        });
        admin.MapGet("/rides", (HttpContext ctx, GrapDbContext db, RideService s, string? q, string? status, string? service, string? cursor, int? pageSize) => { var a = ctx.Actor(); a.Require(Roles.Dispatcher, Roles.Support, Roles.Operations, Roles.Finance, Roles.Approver); var rides = db.Set<Ride>().Where(r => r.ZoneId == a.ZoneId).OrderByDescending(r => r.CreatedAt).ThenByDescending(r => r.Id).ToList().Where(r => (status == null || status == "ACTIVE" && RideStates.IsActive(r.Status) || r.Status == status) && (service == null || r.ServiceTypeCode == service) && (string.IsNullOrWhiteSpace(q) || r.Code.Contains(q, StringComparison.OrdinalIgnoreCase) || s.Find<User>(r.CustomerId).Name.Contains(q, StringComparison.OrdinalIgnoreCase))); return Page(rides.Select(r => s.Snapshot(a, r)), cursor, pageSize); });
        admin.MapGet("/rides/{id}", (string id, HttpContext ctx, RideService s) => s.Snapshot(ctx.Actor(), s.AuthorizedRide(ctx.Actor(), id)));
        foreach (var (route, command) in new[] { ("reassignment-requests", "reassign"), ("end-early", "end-early") }) admin.MapPost("/rides/{id}/" + route, (string id, RideCommand body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s, GrapDbContext db) => Write(ctx, executor, secrets, body, async () => { ctx.Actor().Require(Roles.Operations, Roles.Dispatcher); var ride = s.Command(ctx.Actor(), id, command, body); await db.SaveChangesAsync(); return s.Snapshot(ctx.Actor(), ride); }, true));
        admin.MapGet("/drivers", (HttpContext ctx, GrapDbContext db, string? q, string? status) => { var a = ctx.Actor(); a.Require(Roles.Operations, Roles.Reviewer, Roles.Dispatcher, Roles.Finance, Roles.Approver); var list = db.Set<Driver>().Where(d => d.ZoneId == a.ZoneId).ToList().Where(d => status == null || d.ReviewStatus == status).Select(d => { var u = db.Set<User>().Single(u => u.Id == d.UserId); return new { d.Id, d.UserId, u.Name, phone = RideService.Mask(u.Phone), u.Status, d.ReviewStatus, d.ServiceTypeCode, d.Vehicle, d.Color, d.Plate, d.Online, d.HeartbeatAt, d.LocationAt, d.Latitude, d.Longitude, d.Rating, d.Version, d.CreatedAt, d.DocumentsExpireAt, d.ReviewReason, healthy = d.Online && d.HeartbeatAt > DateTime.UtcNow.AddSeconds(-30) && d.LocationAt > DateTime.UtcNow.AddSeconds(-30), onRide = db.Set<Assignment>().Any(x => x.DriverId == d.Id && x.EndedAt == null) }; }).Where(d => string.IsNullOrWhiteSpace(q) || d.Name.Contains(q, StringComparison.OrdinalIgnoreCase) || d.Plate.Contains(q, StringComparison.OrdinalIgnoreCase)); return new { items = list, serverTime = DateTime.UtcNow }; });
        admin.MapPost("/drivers/{id}/review-decisions", (string id, ReviewRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s, GrapDbContext db, IWebHostEnvironment env) => Write(ctx, executor, secrets, body, () => { var a = ctx.Actor(); a.Require(Roles.Reviewer); var d = s.Find<Driver>(id); a.Scope(d.ZoneId); if (body.ExpectedVersion != d.Version || d.ReviewStatus != "PENDING_REVIEW") throw new RuleException("VERSION_CONFLICT", "Hồ sơ đã thay đổi.", 409, d.Version); RideService.RequireReason(body.ReasonCode); if (body.Decision is not ("APPROVED" or "REJECTED")) throw new RuleException("VALIDATION_ERROR", "Quyết định không hợp lệ.", 400); if (body.Decision == "APPROVED" && (!env.IsDevelopment() || !d.Id.StartsWith("driver-", StringComparison.Ordinal))) { var latest = db.Set<DriverDocument>().Where(doc => doc.DriverId == id).ToList().GroupBy(doc => doc.Type).Select(g => g.OrderByDescending(doc => doc.Version).First()).ToList(); if (RequiredDocuments.Any(type => !latest.Any(doc => doc.Type == type && doc.Status == "APPROVED" && doc.ExpiresAt > DateTime.UtcNow))) throw new RuleException("DOCUMENTS_REQUIRED", "Cần đủ bốn loại giấy tờ đã được xác minh và còn hạn.", 422); d.DocumentsExpireAt = latest.Min(doc => doc.ExpiresAt); } d.ReviewStatus = body.Decision; d.ReviewReason = body.ReasonCode; d.Version++; db.Add(new Notification { UserId = d.UserId, Kind = "application", EntityId = d.Id, Title = "Hồ sơ tài xế đã cập nhật", Body = body.Decision == "APPROVED" ? "Hồ sơ đã được phê duyệt." : "Hồ sơ cần được bổ sung. Mở ứng dụng để xem chi tiết." }); s.Audit(a, "driver.review." + body.Decision, id, body.ReasonCode); return Task.FromResult<object?>(d); }));
        admin.MapGet("/customers", (HttpContext ctx, GrapDbContext db, string? q) => { var a = ctx.Actor(); a.Require(Roles.Operations, Roles.Security, Roles.Support); return new { items = db.Set<User>().Where(u => u.Role == Roles.Customer && u.ZoneId == a.ZoneId).ToList().Where(u => string.IsNullOrWhiteSpace(q) || u.Name.Contains(q, StringComparison.OrdinalIgnoreCase)).Select(u => new { u.Id, u.Name, phone = RideService.Mask(u.Phone), u.Status, u.CreatedAt, u.Version, totalRides = db.Set<Ride>().Count(r => r.CustomerId == u.Id) }) }; });
        admin.MapPost("/users/{id}/restrictions", (string id, RestrictionRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s, GrapDbContext db) => Write(ctx, executor, secrets, body, () => { var a = ctx.Actor(); a.Require(Roles.Operations, Roles.Security); var user = s.Find<User>(id); a.Scope(user.ZoneId); if (Roles.Staff.Contains(user.Role) && a.Role != Roles.Security) throw new RuleException("FORBIDDEN", "Chỉ quản trị bảo mật được khóa nhân sự.", 403); if (user.Id == a.Id) throw new RuleException("FORBIDDEN", "Không thể khóa chính mình.", 403); RideService.RequireReason(body.ReasonCode); if (body.ExpectedVersion != user.Version) throw new RuleException("VERSION_CONFLICT", "Tài khoản đã thay đổi."); user.Status = body.Blocked ? "SUSPENDED" : "ACTIVE"; user.Version++; if (body.Blocked) { foreach (var session in db.Set<Session>().Where(ses => ses.UserId == id && ses.RevokedAt == null)) session.RevokedAt = DateTime.UtcNow; var d = db.Set<Driver>().SingleOrDefault(d => d.UserId == id); if (d != null) d.Online = false; } s.Audit(a, "user.restriction", id, body.ReasonCode); return Task.FromResult<object?>(new { user.Id, user.Status, user.Version }); }));
        admin.MapGet("/fare-policies", (HttpContext ctx, GrapDbContext db) => { var a = ctx.Actor(); a.Require(Roles.Operations, Roles.Dispatcher); return new { items = db.Set<FarePolicy>().Where(p => p.ZoneId == a.ZoneId).OrderBy(p => p.ServiceTypeCode).ThenByDescending(p => p.Version).ToList() }; });
        admin.MapPost("/fare-policies", (FareRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s, GrapDbContext db) => Write(ctx, executor, secrets, body, () => { var a = ctx.Actor(); a.Require(Roles.Operations); if (body.ServiceTypeCode is not ("BIKE" or "CAR_4" or "CAR_7") || body.BaseFare < 0 || body.PerKm < 0 || body.PerMinute < 0 || body.MinimumFare < 0 || body.ServiceFee < 0 || body.CommissionRate is < 0 or > 0.5m) throw new RuleException("VALIDATION_ERROR", "Giá hoặc hoa hồng không hợp lệ.", 400); var version = db.Set<FarePolicy>().Where(p => p.ZoneId == a.ZoneId && p.ServiceTypeCode == body.ServiceTypeCode).Select(p => (int?)p.Version).Max() ?? 0; var policy = new FarePolicy { ZoneId = a.ZoneId, ServiceTypeCode = body.ServiceTypeCode, Name = body.Name, BaseFare = body.BaseFare, PerKm = body.PerKm, PerMinute = body.PerMinute, MinimumFare = body.MinimumFare, ServiceFee = body.ServiceFee, CommissionRate = body.CommissionRate, Version = version + 1, CreatedBy = a.Id }; db.Add(policy); s.Audit(a, "fare.draft", policy.Id); return Task.FromResult<object?>(policy); }, status: 201));
        admin.MapPost("/fare-policies/{id}/publish", (string id, PublishRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s) => Write(ctx, executor, secrets, body, () => { var a = ctx.Actor(); a.Require(Roles.Operations); var p = s.Find<FarePolicy>(id); a.Scope(p.ZoneId); if (p.Status != "DRAFT" || p.Version != body.ExpectedVersion) throw new RuleException("VERSION_CONFLICT", "Bản giá không còn ở trạng thái nháp."); RideService.RequireReason(body.ReasonCode); if (body.EffectiveAt < DateTime.UtcNow.AddMinutes(-1)) throw new RuleException("VALIDATION_ERROR", "Không thể phát hành hồi tố.", 400); p.Status = "PUBLISHED"; p.EffectiveFrom = body.EffectiveAt; s.Audit(a, "fare.publish", id, body.ReasonCode); return Task.FromResult<object?>(p); }));
        admin.MapGet("/service-zones", (HttpContext ctx, GrapDbContext db) => { ctx.Actor().Require(Roles.Operations, Roles.Dispatcher); return new { items = db.Set<ServiceZone>().Where(z => z.Id == ctx.Actor().ZoneId).ToList() }; });
        admin.MapGet("/finance", (HttpContext ctx, GrapDbContext db, RideService s) => { var a = ctx.Actor(); a.Require(Roles.Finance, Roles.Approver); var rideIds = db.Set<Ride>().Where(r => r.ZoneId == a.ZoneId).Select(r => r.Id).ToList(); var payments = db.Set<Payment>().Where(p => rideIds.Contains(p.RideId)).ToList(); var driverIds = db.Set<Driver>().Where(d => d.ZoneId == a.ZoneId).Select(d => d.Id).ToList(); return new { payments = payments.OrderByDescending(p => p.CreatedAt).Take(100).Select(p => new { p.Id, p.RideId, rideCode = s.Find<Ride>(p.RideId).Code, p.Status, p.PayableAmount, p.PaidAmount, p.CreatedAt, driverName = s.Find<User>(s.Find<Driver>(p.DriverId).UserId).Name }), totalPayable = payments.Sum(p => p.PayableAmount), collected = payments.Sum(p => p.PaidAmount), outstanding = payments.Sum(p => p.PayableAmount - p.PaidAmount), journals = db.Set<Journal>().Include(j => j.Entries).Where(j => rideIds.Contains(j.RideId)).OrderByDescending(j => j.CreatedAt).Take(50).ToList(), drivers = driverIds.Select(id => new { id, name = s.Find<User>(s.Find<Driver>(id).UserId).Name, balance = s.Balance(id) }), remittances = db.Set<Remittance>().Where(r => driverIds.Contains(r.DriverId)).OrderByDescending(r => r.CreatedAt).ToList() }; });
        admin.MapPost("/cash-remittances", (RemittanceRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s, GrapDbContext db) => Write(ctx, executor, secrets, body, () => { var a = ctx.Actor(); a.Require(Roles.Finance); var d = s.Find<Driver>(body.DriverId); a.Scope(d.ZoneId); if (body.Amount <= 0 || string.IsNullOrWhiteSpace(body.Reference) || body.Evidence.Length < 5) throw new RuleException("VALIDATION_ERROR", "Cần số tiền, mã giao dịch và bằng chứng.", 400); var remittance = new Remittance { DriverId = d.Id, Amount = body.Amount, Reference = body.Reference, Evidence = body.Evidence, MakerId = a.Id }; db.Add(remittance); s.Audit(a, "remittance.request", remittance.Id, body.Reference); return Task.FromResult<object?>(remittance); }, true, 201));
        admin.MapPost("/cash-remittances/{id}/approve", (string id, VersionRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s, GrapDbContext db) => Write(ctx, executor, secrets, body, () => { var a = ctx.Actor(); a.Require(Roles.Approver); var r = s.Find<Remittance>(id); a.Scope(s.Find<Driver>(r.DriverId).ZoneId); if (r.MakerId == a.Id) throw new RuleException("MAKER_CHECKER_VIOLATION", "Người lập không được tự duyệt.", 403); if (r.Status != "REQUESTED" || r.Version != body.ExpectedVersion) throw new RuleException("VERSION_CONFLICT", "Yêu cầu đã thay đổi."); var entries = db.Set<LedgerEntry>().Where(e => e.OwnerId == r.DriverId && e.Account == "DRIVER_PAYABLE").ToList(); var debt = Math.Max(0, entries.Sum(e => e.Debit - e.Credit)); if (r.Amount > debt) throw new RuleException("INVALID_AMOUNT", "Số tiền vượt công nợ hiện tại.", 422); r.ApproverId = a.Id; r.Status = "APPROVED"; r.Version++; s.Post(new Journal { RideId = "remittance:" + id, OperationKey = "remittance:" + id, Description = "Xác nhận nộp công nợ " + r.Reference, Entries = [new() { Account = "BANK_CASH", Debit = r.Amount }, new() { Account = "DRIVER_PAYABLE", OwnerId = r.DriverId, Credit = r.Amount }] }); s.Audit(a, "remittance.approve", id, r.Reference); return Task.FromResult<object?>(r); }, true));
        admin.MapGet("/support/tickets", (HttpContext ctx, GrapDbContext db, string? status) => { var a = ctx.Actor(); a.Require(Roles.Support, Roles.Operations); return new { items = db.Set<SupportTicket>().Where(t => t.ZoneId == a.ZoneId && (status == null || t.Status == status)).OrderByDescending(t => t.CreatedAt).ToList().Select(t => new { t.Id, t.Subject, t.Category, t.Priority, t.Status, t.Version, t.CreatedAt, t.RideId, t.RequesterId, requesterName = db.Set<User>().Single(u => u.Id == t.RequesterId).Name, t.AssigneeId }) }; });
        admin.MapPost("/support/tickets/{id}/transitions", (string id, TicketTransition body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s) => Write(ctx, executor, secrets, body, () => { var a = ctx.Actor(); a.Require(Roles.Support); var t = s.Find<SupportTicket>(id); a.Scope(t.ZoneId); if (body.ExpectedVersion != t.Version) throw new RuleException("VERSION_CONFLICT", "Yêu cầu đã thay đổi."); var allowed = t.Status switch { "OPEN" => new[] { "IN_PROGRESS" }, "IN_PROGRESS" => new[] { "RESOLVED", "ESCALATED" }, "ESCALATED" => new[] { "IN_PROGRESS", "RESOLVED" }, "RESOLVED" => new[] { "OPEN", "CLOSED" }, _ => Array.Empty<string>() }; if (!allowed.Contains(body.Status)) throw new RuleException("INVALID_TICKET_STATE", "Không thể chuyển sang trạng thái này."); RideService.RequireReason(body.ReasonCode); t.Status = body.Status; t.AssigneeId = a.Id; t.Version++; s.Audit(a, "ticket." + body.Status, id, body.ReasonCode); return Task.FromResult<object?>(t); }));
        admin.MapGet("/safety-incidents", (HttpContext ctx, GrapDbContext db) => { var a = ctx.Actor(); a.Require(Roles.Support, Roles.Operations); return new { items = db.Set<SafetyIncident>().Where(i => db.Set<Ride>().Any(r => r.Id == i.RideId && r.ZoneId == a.ZoneId)).OrderByDescending(i => i.CreatedAt).ToList() }; });
        admin.MapPost("/safety-incidents/{id}/acknowledge", (string id, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s) => Write(ctx, executor, secrets, new { id }, () => { var a = ctx.Actor(); a.Require(Roles.Support); var incident = s.Find<SafetyIncident>(id); s.AuthorizedRide(a, incident.RideId); incident.Status = "ACKNOWLEDGED"; incident.AcknowledgedAt = DateTime.UtcNow; s.Audit(a, "safety.acknowledged", id); return Task.FromResult<object?>(incident); }));
        admin.MapGet("/audit-logs", (HttpContext ctx, GrapDbContext db, string? q, string? cursor, int? pageSize) => { var a = ctx.Actor(); a.Require(Roles.Security, Roles.Operations); return Page(db.Set<AuditLog>().Where(l => l.ZoneId == a.ZoneId).OrderByDescending(l => l.CreatedAt).ThenByDescending(l => l.Id).ToList().Where(l => string.IsNullOrWhiteSpace(q) || l.Action.Contains(q, StringComparison.OrdinalIgnoreCase) || l.ActorName.Contains(q, StringComparison.OrdinalIgnoreCase)), cursor, pageSize); });
        admin.MapGet("/system", (HttpContext ctx, GrapDbContext db) => { ctx.Actor().Require(Roles.Operations, Roles.Security); return new { database = db.Database.ProviderName, pendingOutbox = db.Set<OutboxMessage>().Count(o => o.PublishedAt == null), deadLetters = db.Set<OutboxMessage>().Count(o => o.PublishedAt == null && o.Attempts >= 10), serverTime = DateTime.UtcNow, capabilities = new { cash = true, payments = false, sms = false, push = ctx.RequestServices.GetRequiredService<IPushSender>().Enabled, documents = appEnvironment(ctx) } }; });
    }
    private static bool appEnvironment(HttpContext ctx) => ctx.RequestServices.GetRequiredService<IWebHostEnvironment>().IsDevelopment();
}
public record RestrictionRequest(int ExpectedVersion, bool Blocked, string ReasonCode);
public record FareRequest(string ServiceTypeCode, string Name, long BaseFare, long PerKm, long PerMinute, long MinimumFare, long ServiceFee, decimal CommissionRate);
public record PublishRequest(int ExpectedVersion, DateTime EffectiveAt, string ReasonCode);
public record TicketTransition(int ExpectedVersion, string Status, string ReasonCode);
public record RemittanceRequest(string DriverId, long Amount, string Reference, string Evidence);
